const esc = (s) => String(s).replace(/[^\x20-\x7E]/g, ' ').replace(/[()\\]/g, ' ')

export function makeDummyPdf(title, subtitle = '') {
  const lines = [
    'BT /F1 20 Tf 72 720 Td',
    `(${esc(title)}) Tj`,
    'ET',
    'BT /F2 12 Tf 72 692 Td',
    `(${esc(subtitle)}) Tj`,
    'ET',
    'BT /F2 10 Tf 72 660 Td',
    '(This is a placeholder PDF generated by the School Portal demo.) Tj',
    'ET',
    'BT /F2 10 Tf 72 645 Td',
    '(In production this would be the actual assignment file uploaded by the admin.) Tj',
    'ET',
  ].join('\n')

  const objects = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 4 0 R /F2 5 0 R >> >> /Contents 6 0 R >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>',
    `<< /Length ${lines.length} >>\nstream\n${lines}\nendstream`,
  ]

  let pdf = '%PDF-1.4\n'
  const offsets = []
  objects.forEach((obj, i) => {
    offsets.push(pdf.length)
    pdf += `${i + 1} 0 obj\n${obj}\nendobj\n`
  })
  const xrefStart = pdf.length
  pdf += `xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`
  offsets.forEach((off) => {
    pdf += `${String(off).padStart(10, '0')} 00000 n \n`
  })
  pdf += `trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xrefStart}\n%%EOF`

  return new Blob([pdf], { type: 'application/pdf' })
}

export function openPdf(title, subtitle) {
  const url = URL.createObjectURL(makeDummyPdf(title, subtitle))
  window.open(url, '_blank', 'noopener')
  window.setTimeout(() => URL.revokeObjectURL(url), 60000)
}
